Lemma art_mfa_step : forall c cl, 1 <= c <= 30 -> art_cls_ok c cl ->
  let tot := Z.of_nat (length (cl_free cl)) + art_cls_new c cl in
  art_cls_mfa' cl tot = cl_mfa cl \/ (4 * tot > cl_mfa cl /\ art_cls_mfa' cl tot = cl_mfa cl + 262144).
